    // @knowledge a851bdee-9b6f-416e-b06d-8dc973536fad@e6614e57a04f451b
    // ir_evt_SessionCompleted_stageId_not_null
    else if (!(Option(e.stageId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "SessionCompleted.stageId 必须存在"))
    // @knowledge a851bdee-9b6f-416e-b06d-8dc973536fad@e6614e57a04f451b
    // ir_evt_SessionCompleted_tenantId_not_null
    else if (!(Option(e.tenantId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "SessionCompleted.tenantId 必须存在"))
    // @knowledge a851bdee-9b6f-416e-b06d-8dc973536fad@e6614e57a04f451b
    // ir_evt_SessionCompleted_timestamp
    else if (!(Option(e.timestamp).isDefined)) Some(iMadzError("EVENT_NO_TIMESTAMP", "SessionCompleted.timestamp 不能为空"))
    else None

  private def firstBadSessionClosed(e: SessionClosed): Option[iMadzError] =
    // @knowledge 12621133-5f2e-4846-85f5-2f067574c49a@22f2787b92975992
    // ir_evt_SessionClosed_sessionId_not_null
    if (!(Option(e.sessionId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "SessionClosed.sessionId 必须存在"))
    // @knowledge 12621133-5f2e-4846-85f5-2f067574c49a@22f2787b92975992
    // ir_evt_SessionClosed_stageId_not_null
    else if (!(Option(e.stageId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "SessionClosed.stageId 必须存在"))
    // @knowledge 12621133-5f2e-4846-85f5-2f067574c49a@22f2787b92975992
    // ir_evt_SessionClosed_tenantId_not_null
    else if (!(Option(e.tenantId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "SessionClosed.tenantId 必须存在"))
    // @knowledge 12621133-5f2e-4846-85f5-2f067574c49a@22f2787b92975992
    // ir_evt_SessionClosed_timestamp
    else if (!(Option(e.timestamp).isDefined)) Some(iMadzError("EVENT_NO_TIMESTAMP", "SessionClosed.timestamp 不能为空"))
    else None

}
